(86, '}\r\n\r\nprivate function handleImageUpload(?array $file): ?string\r\n{\r\n    if (!$file || $file[&#039;error&#039;] !== UPLOAD_ERR_OK) {\r\n        return null;\r\n    }\r\n\r\n    $uploadDir = &#039;uploads/articles/&#039;;\r\n    if (!is_dir($uploadDir)) {\r\n        mkdir($uploadDir, 0755, true);\r\n    }\r\n\r\n    // Vérification du type MIME réel\r\n    $finfo = finfo_open(FILEINFO_MIME_TYPE);\r\n    $mime = finfo_file($finfo, $file[&#039;tmp_name&#039;]);\r\n    $allowedMimes = [&#039;image/jpeg&#039;, &#039;image/png&#039;, &#039;image/gif&#039;, &#039;image/webp&#039;];\r\n\r\n    if (!in_array($mime, $allowedMimes)) {\r\n        throw new \\Exception(&quot;Format d&#039;image non supporté&quot;);\r\n    }\r\n\r\n    $extension = pathinfo($file[&#039;name&#039;], PATHINFO_EXTENSION);\r\n    $filename = uniqid(&#039;article_&#039;) . &#039;.&#039; . $extension;\r\n    $destination = $uploadDir . $filename;\r\n\r\n    if (!move_uploaded_file($file[&#039;tmp_name&#039;], $destination)) {\r\n        throw new \\Exception(&quot;Erreur lors du téléchargement de l&#039;image&quot;);\r\n    }\r\n\r\n    return $destination;\r\n}\r\nAméliorations apportées\r\nSéparation des responsabilités :\r\n\r\nExtraction de la logique de traitement d&#039;image dans une méthode dédiée\r\nUtilisation d&#039;une classe Utils pour les fonctions communes\r\nSécurité renforcée :\r\n\r\nVérification du type MIME réel des fichiers\r\nGestion centralisée des erreurs avec try/catch\r\nValidation plus stricte des permissions\r\nQualité de code :\r\n\r\nChemins de vues normalisés\r\nTypage des retours et paramètres (à ajouter selon version PHP)\r\nMessages d&#039;erreur plus précis\r\nMaintenabilité :\r\n\r\nCode plus facile à tester unitairement\r\nMeilleure organisation des dépendances\r\nPour compléter cette refactorisation, vous devriez :\r\n\r\nCréer une classe Utils avec les méthodes communes\r\nMettre à jour votre fichier admin.php pour qu&#039;il utilise la nouvelle version\r\nVérifier que toutes les dépendances sont correctement chargées\r\nCette version devrait résoudre vos problèmes tout en offrant une base plus solide pour les évolutions ', '2025-05-31 00:16:23', 291, 15),
(87, 'Code plus facile à tester unitairement\r\nMeilleure organisation des dépendances\r\nPour compléter cette refactorisation, vous devriez :\r\n\r\nCréer une classe Utils avec les méthodes communes\r\nMettre à jour votre fichier admin.php pour qu&amp;#039;il utilise la nouvelle version\r\nVérifier que toutes les dépendances sont correctement chargées\r\nCette version devrait résoudre vos problèmes tout en offrant une base plus solide pour les évolutions', '2025-05-31 00:16:32', 291, 15),
(88, 'Code plus facile à tester unitairement\r\nMeilleure organisation des dépendances\r\nPour compléter cette refactorisation, vous devriez :\r\n\r\nCréer une classe Utils avec les méthodes communes\r\nMettre à jour votre fichier admin.php pour qu&amp;#039;il utilise la nouvelle version\r\nVérifier que toutes les dépendances sont correctement chargées\r\nCette version devrait résoudre vos problèmes tout en offrant une base plus solide pour les évolutions', '2025-05-31 00:16:49', 291, 4),
